function forecast(series){
 const xs=series.map((_,i)=>i+1), n=series.length, sx=xs.reduce((a,b)=>a+b,0),sy=series.reduce((a,b)=>a+b,0);
 const sxx=xs.reduce((a,b)=>a+b*b,0),sxy=xs.reduce((a,x,i)=>a+x*series[i],0);
 const b=(n*sxy-sx*sy)/(n*sxx-sx*sx), a=(sy-b*sx)/n;
 return {a,b,demand:Math.max(0,Math.round(a+b*(n+1))),trend:b>3?'Tăng':b< -3?'Giảm':'Ổn định'};
}
function computeRun(s){
 const runId=id('PT',s.aiRuns);
 return {id:runId,time:timeNow(),createdBy:session||'quanlykho',period:'Kỳ 7',warehouse:wh,rows:s.products.filter(p=>p.active).map(p=>{
   const {a,b,demand,trend}=forecast(p.series),stock=s.stocks[p.sku]||0;
   const status=(stock===0&&demand===0)?'Bình thường':stock<demand?'Thiếu':stock>=1.5*demand?'Dư':'Bình thường';
   return {id:`${runId}-${p.sku}`,sku:p.sku,warehouse:wh,trend,demand,stock,status,suggest:Math.max(demand-stock,0),slope:b,a};
 })};
}
function initialState(){
 const s={products:baseProducts.map(([sku,name,group,series])=>({sku,name,group,series,unit:'cái',active:true})),stocks:Object.fromEntries(baseProducts.map(([sku,,,,stock])=>[sku,stock])),
  requests:[{id:'YCN0001',date:'25/10/2026',by:'Bộ phận mua hàng',source:'Thủ công',status:'Chờ xử lý',lines:[{sku:'HH002',qty:40,decisionId:null}]}],
  orders:[],receipts:[],outRequests:[{id:'YCX0001',date:'26/10/2026',by:'Bộ phận kinh doanh',status:'Chờ xử lý',lines:[{sku:'HH007',qty:12}]}],issues:[],counts:[],movements:[],aiRuns:[],decisions:[],alertRead:{},activity:[]};
 s.aiRuns.push(computeRun(s));return s;
}
function loadState(){try {const x=JSON.parse(localStorage.getItem(STORE_KEY));if(x?.products&&x?.aiRuns&&x?.decisions)return x;}catch(e){}return initialState()}
