let timer=null;
function alertText(status){return status==='Thiếu'?'Nguy cơ thiếu':status==='Dư'?'Nguy cơ dư':'Bình thường'}
function badge(text,tone){let t=tone;if(!t){t=/Thiếu|Từ chối|Hủy|Lỗi/.test(text)?'red':/Hoàn thành|Đã xác nhận|Chấp nhận|Bình thường|Đã duyệt|Đã xử lý/.test(text)?'green':/Dư|Chờ|Đang|Nháp/.test(text)?'amber':/Điều chỉnh|Tăng/.test(text)?'blue':'gray'}return `<span class="badge badge-${t}">${h(text)}</span>`}
function btn(label,action,opts={}){return `<button class="btn ${opts.cls||'btn-light'} ${opts.sm?'btn-sm':''}" data-action="${h(action)}" ${opts.key?'data-key="'+h(opts.key)+'"':''} ${opts.disabled?'disabled':''}>${label}</button>`}
function table(headers,body,empty='Chưa có dữ liệu phù hợp'){return `<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty">${h(empty)}</td></tr>`}</tbody></table></div>`}
function filterRows(arr,getText){const search=ui.search.trim().toLowerCase();return arr.filter(p=>!search||getText(p).toLowerCase().includes(search))}
function setSearch(){return `<input class="field input-search" data-filter="search" value="${h(ui.search)}" placeholder="⌕ Tìm kiếm..." aria-label="Tìm kiếm" />`}
function pageHeading(title,subtitle,actions=''){return `<div class="page-heading"><div><span class="eyebrow">QUẢN LÝ KHO THÔNG MINH</span><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function cardTitle(title,aside=''){return `<div class="card-title"><h2>${title}</h2><div class="meta">${aside}</div></div>`}
function metric(label,value,icon,bg,note){return `<div class="card metric"><div class="metric-icon metric-${bg}">${icon}</div><div class="metric-label">${label}</div><div class="metric-value num">${fmt(value)}</div><div class="metric-note">${note}</div></div>`}
