function totals(){const rows=latestRun().rows;return {missing:rows.filter(r=>r.status==='Thiếu').length,extra:rows.filter(r=>r.status==='Dư').length,ok:rows.filter(r=>r.status==='Bình thường').length,sum:rows.filter(r=>r.status==='Thiếu').reduce((a,r)=>a+r.suggest,0)}}
