function modal(title,body,footer='',wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay" data-action="closeOverlay"><div class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-header"><h2>${title}</h2><button class="btn btn-light btn-icon" data-action="closeModal" aria-label="Đóng">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`}
