function selectField(label,name,opts,sel){return `<div class="form-group"><label for="f-${name}">${label}</label><select class="field" id="f-${name}" name="${h(name)}" required>${opts.map(([v,l])=>`<option value="${h(v)}" ${String(sel)===String(v)?'selected':''}>${h(l)}</option>`).join('')}</select></div>`}
