function addMovement(sku,delta,kind,source){const before=state.stocks[sku]||0;if(before+delta<0)throw new Error('Không đủ số lượng tồn để thực hiện giao dịch.');state.stocks[sku]=before+delta;state.movements.unshift({id:id('BD',state.movements),sku,delta,qty:Math.abs(delta),kind,source,before,after:before+delta,date:timeNow(),by:currentUser().name});}
function eventAction(action,key){if(action==='closeOverlay'){return;}if(action==='closeModal'){closeModal();return;}
 if(['newProduct','editProduct','viewProduct','newReq','viewReq','makeOrder','viewOrder','makeReceipt','viewReceipt','newOutReq','viewOutReq','viewIssue','newCount','viewCount','movements','viewAI','viewAlert','decideAccept','decideAdjust','decideReject','switchRole'].includes(action))return showModalAction(action,key);
 switch(action){
 case 'gotoAI':ui.page='ai';ui.status='all';render();break;
 case 'gotoAlerts':ui.page='alerts';ui.status='all';render();break;
 case 'setRole':{const u=users.find(x=>x.username===key);if(!u)return;session=u.username;localStorage.setItem(SESS_KEY,session);ui.page='dashboard';ui.search='';ui.status='all';closeModal();render();toast(`Đã chuyển sang vai trò ${u.label}.`);break;}
 case 'logout':session='';localStorage.removeItem(SESS_KEY);closeModal();render();break;
 case 'reset':if(!confirm('Đặt lại toàn bộ dữ liệu demo về trạng thái ban đầu? Tất cả thao tác trước đó sẽ mất.'))return;state=initialState();save();ui.page='dashboard';ui.search='';ui.status='all';closeModal();render();toast('Đã khôi phục dữ liệu demo ban đầu.');break;
 case 'runAI':if(!isManager())return toast('Chỉ Quản lý kho được thực hiện phân tích AI.',true);state.aiRuns.push(computeRun(state));note('Thực hiện phân tích AI',`${state.products.length} SKU · ${latestRun().id}`);render();toast('Đã tạo lần phân tích mới từ tồn kho hiện tại.');break;
 case 'markAlert':state.alertRead[key]=true;save();closeModal();render();toast('Đã đánh dấu cảnh báo là đã xem.');break;
 case 'viewAIFromAlert':closeModal();ui.page='ai';ui.chosenSku=latestRun().rows.find(r=>r.id===key)?.sku||'HH004';ui.status='all';render();showAI(key);break;
 case 'createFromAI':{const d=state.decisions.find(x=>x.id===key);if(!d||!isManager()||d.type==='Từ chối')return toast('Không thể tạo yêu cầu từ quyết định này.',true);if(state.requests.find(r=>r.lines.some(l=>l.decisionId===d.id)))return toast('Quyết định này đã có yêu cầu nhập liên kết.',true);if(d.qty<=0)return toast('Số lượng nhập phải lớn hơn 0.',true);const r={id:id('YCN',state.requests),date:today(),by:currentUser().name,source:'AI',status:'Nháp',lines:[{sku:d.sku,qty:d.qty,decisionId:d.id}]};state.requests.push(r);note('Tạo yêu cầu nhập từ AI',`${r.id} · ${d.sku} · ${d.qty} đơn vị`);closeModal();ui.page='inbound';ui.inboundTab='requests';ui.search='';render();toast(`Đã tạo ${r.id} ở trạng thái Nháp. Tồn kho chưa thay đổi.`);break;}
 case 'makeIssue':{if(!canOperate())return toast('Chỉ nhân viên kho/Quản lý kho được lập phiếu xuất.',true);const r=state.outRequests.find(x=>x.id===key);if(!r||r.status!=='Chờ xử lý')return toast('Yêu cầu không còn chờ xử lý.',true);const bad=r.lines.find(l=>l.qty>(state.stocks[l.sku]||0));if(bad)return toast(`${bad.sku} chỉ còn ${state.stocks[bad.sku]} đơn vị, không đủ để lập phiếu xuất.`,true);const item={id:id('PX',state.issues),reqId:r.id,warehouse:wh,date:today(),status:'Nháp',lines:r.lines.map(l=>({...l,position:position(l.sku)}))};state.issues.push(item);r.status='Đã lập phiếu';note('Lập phiếu xuất',`${item.id} từ ${r.id}`);ui.outboundTab='issues';render();toast(`Đã tạo ${item.id} ở trạng thái Nháp.`);break;}
 case 'confirmIssue':{if(!canOperate())return toast('Không đủ quyền xác nhận phiếu xuất.',true);const r=state.issues.find(x=>x.id===key);if(!r||r.status!=='Nháp')return toast('Phiếu xuất đã được xử lý.',true);const bad=r.lines.find(l=>l.qty>(state.stocks[l.sku]||0));if(bad)return toast(`Không đủ tồn ${bad.sku}: chỉ còn ${state.stocks[bad.sku]} đơn vị.`,true);if(!confirm(`Xác nhận phiếu xuất ${r.id} và TRỪ tồn kho thực tế?`))return;r.lines.forEach(l=>addMovement(l.sku,-l.qty,'Xuất',r.id));r.status='Đã xác nhận';const req=state.outRequests.find(x=>x.id===r.reqId);if(req)req.status='Hoàn thành';note('Xác nhận xuất kho',`${r.id} · Đã trừ tồn`);render();toast('Đã xác nhận phiếu xuất và cập nhật tồn kho.');break;}
 case 'confirmReceipt':{if(!canOperate())return toast('Không đủ quyền xác nhận phiếu nhập.',true);const r=state.receipts.find(x=>x.id===key);if(!r||r.status!=='Nháp')return toast('Phiếu nhập đã được xử lý.',true);if(!confirm(`Xác nhận phiếu nhập ${r.id} và CỘNG tồn kho thực tế?`))return;r.lines.forEach(l=>addMovement(l.sku,l.qty,'Nhập',r.id));r.status='Đã xác nhận';const order=state.orders.find(o=>o.id===r.orderId);if(order){order.status='Hoàn thành';const req=state.requests.find(x=>x.id===order.reqId);if(req)req.status='Hoàn thành';}note('Xác nhận nhập kho',`${r.id} · Đã cộng tồn`);render();toast('Đã xác nhận phiếu nhập và cập nhật tồn kho.');break;}
 case 'approveCount':{if(!isManager())return toast('Chỉ Quản lý kho được phê duyệt kiểm kê.',true);const c=state.counts.find(x=>x.id===key);if(!c||c.status!=='Chờ phê duyệt')return toast('Đợt kiểm kê đã được xử lý.',true);if(state.stocks[c.sku]!==c.systemQty)return toast('Tồn đã thay đổi từ lúc kiểm kê. Cần thực hiện kiểm kê lại.',true);if(!confirm(`Phê duyệt điều chỉnh ${c.sku} từ ${c.systemQty} thành ${c.actualQty}?`))return;const delta=c.actualQty-c.systemQty;if(delta!==0)addMovement(c.sku,delta,'Kiểm kê',c.id);c.status='Đã duyệt';c.approvedBy=currentUser().name;note('Phê duyệt kiểm kê',`${c.id} · Chênh lệch ${delta>0?'+':''}${delta}`);render();toast('Đã phê duyệt kiểm kê và cập nhật tồn khi có chênh lệch.');break;}
 case 'exportReport':{const lines=['SKU,Tên hàng hóa,Nhóm hàng,Kho,Tồn hiện tại,Đơn vị tính',...state.products.map(p=>[p.sku,`"${p.name.replaceAll('"','""')}"`,p.group,wh,state.stocks[p.sku],p.unit].join(','))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='KhoAI_bao_cao_ton_kho.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Đã xuất CSV tồn kho phục vụ demo.');break;}
 }}
function submitForm(form){const data=Object.fromEntries(new FormData(form));const kind=form.dataset.form;
 const qty=Number(data.qty);
 function positive(v,label='Số lượng'){const n=Number(v);if(!Number.isInteger(n)||n<=0)throw new Error(`${label} phải là số nguyên lớn hơn 0.`);return n}
 function nonnegative(v,label='Số lượng'){const n=Number(v);if(!Number.isInteger(n)||n<0)throw new Error(`${label} phải là số nguyên không âm.`);return n}
 if(kind==='login'){const u=users.find(x=>x.username===data.username);if(!u||data.password!=='123456')throw new Error('Tài khoản hoặc mật khẩu demo không hợp lệ.');session=u.username;localStorage.setItem(SESS_KEY,session);ui.page='dashboard';closeModal();render();toast(`Xin chào ${u.name}!`);return}
 if(kind==='addProduct'){
 if(currentUser().role!=='admin')throw new Error('Không có quyền chỉnh danh mục.');const sku=data.sku.trim().toUpperCase();if(!/^HH\d{3,}$/.test(sku))throw new Error('Mã SKU cần dạng HH021, HH022...');if(state.products.find(x=>x.sku===sku))throw new Error('Mã SKU đã tồn tại.');const p={sku,name:data.name.trim(),group:data.group,unit:data.unit.trim(),series:[0,0,0,0,0,0],active:true};if(!p.name||!p.unit)throw new Error('Cần nhập tên và đơn vị tính.');state.products.push(p);state.stocks[sku]=0;note('Thêm hàng hóa',`${sku} · ${p.name}`);
 }else if(kind==='editProduct'){
 if(currentUser().role!=='admin')throw new Error('Không có quyền chỉnh danh mục.');const p=state.products.find(x=>x.sku===data.sku);if(!p)throw new Error('Không tìm thấy SKU.');p.name=data.name.trim();p.group=data.group;p.active=data.active==='true';note('Cập nhật hàng hóa',`${p.sku} · ${p.name}`);
 }else if(kind==='newReq'){
 if(!canBuy())throw new Error('Không có quyền lập yêu cầu nhập.');const n=positive(qty);const r={id:id('YCN',state.requests),date:today(),by:currentUser().name,source:'Thủ công',status:'Chờ xử lý',lines:[{sku:data.sku,qty:n,decisionId:null}]};state.requests.push(r);note('Tạo yêu cầu nhập',`${r.id} · ${data.sku} · ${n} đơn vị`);ui.inboundTab='requests';
 }else if(kind==='makeOrder'){
 if(!canBuy())throw new Error('Không có quyền lập đơn đặt.');const r=state.requests.find(x=>x.id===data.reqId);if(!r||['Đã đặt hàng','Hoàn thành'].includes(r.status))throw new Error('Yêu cầu đã được xử lý.');const order={id:id('DDH',state.orders),reqId:r.id,supplier:data.supplier,date:today(),expected:data.expected,status:'Đã đặt',lines:r.lines.map(l=>({sku:l.sku,qty:l.qty}))};state.orders.push(order);r.status='Đã đặt hàng';note('Lập đơn đặt hàng',`${order.id} từ ${r.id}`);ui.inboundTab='orders';
 }else if(kind==='makeReceipt'){
 if(!canOperate())throw new Error('Không có quyền lập phiếu nhập.');const order=state.orders.find(x=>x.id===data.orderId);if(!order||order.status==='Hoàn thành')throw new Error('Đơn đặt hàng đã hoàn thành.');if(state.receipts.some(x=>x.orderId===order.id))throw new Error('Đơn đặt hàng đã có phiếu nhập; không lập trùng phiếu trong demo.');const lines=order.lines.map((l,i)=>({sku:l.sku,qty:positive(data['qty'+i],'Số lượng thực nhận'),orderedQty:l.qty,position:data['pos'+i]}));const rec={id:id('PN',state.receipts),orderId:order.id,warehouse:wh,date:today(),status:'Nháp',lines};state.receipts.push(rec);note('Lập phiếu nhập nháp',`${rec.id} từ ${order.id}`);ui.inboundTab='receipts';
 }else if(kind==='newOutReq'){
 if(!canSell())throw new Error('Không có quyền tạo yêu cầu xuất.');const n=positive(qty);const r={id:id('YCX',state.outRequests),date:today(),by:currentUser().name,status:'Chờ xử lý',lines:[{sku:data.sku,qty:n}]};state.outRequests.push(r);note('Tạo yêu cầu xuất',`${r.id} · ${data.sku} · ${n} đơn vị`);ui.outboundTab='requests';
 }else if(kind==='newCount'){
 if(!canOperate())throw new Error('Không có quyền tạo đợt kiểm kê.');const n=nonnegative(data.actualQty,'Lượng kiểm đếm thực tế');if(state.counts.some(c=>c.sku===data.sku&&c.status==='Chờ phê duyệt'))throw new Error('Mặt hàng này đang có đợt kiểm kê chờ phê duyệt.');const c={id:id('KK',state.counts),sku:data.sku,systemQty:state.stocks[data.sku],actualQty:n,status:'Chờ phê duyệt',createdBy:currentUser().name,date:today()};state.counts.push(c);note('Ghi nhận kiểm kê',`${c.id} · ${c.sku} · Thực tế ${n}`);
 }else if(kind==='saveDecision'){
 if(!isManager())throw new Error('Chỉ Quản lý kho được quyết định AI.');const r=latestRun().rows.find(x=>x.id===data.resultId);if(!r||r.suggest===0)throw new Error('Không tìm thấy đề xuất cần xác nhận.');if(decisionFor(r))throw new Error('Đề xuất đã được xác nhận.');const type=data.type;if(!['Chấp nhận','Điều chỉnh','Từ chối'].includes(type))throw new Error('Loại quyết định không hợp lệ.');const n=type==='Từ chối'?0:type==='Chấp nhận'?r.suggest:positive(data.qty,'Số lượng điều chỉnh');if(type!=='Chấp nhận'&&!data.reason.trim())throw new Error('Vui lòng ghi rõ lý do.');const d={id:id('QD',state.decisions),resultId:r.id,runId:latestRun().id,sku:r.sku,type,qty:n,adjustedQuantity:type==='Điều chỉnh'?n:null,reason:data.reason.trim(),by:currentUser().name,date:timeNow()};state.decisions.push(d);note('Xác nhận đề xuất AI',`${r.sku}: ${type} · ${n} đơn vị`);
 }else throw new Error('Biểu mẫu không được hỗ trợ.');
 save();closeModal();render();toast('Đã lưu thành công.');
}
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();try{submitForm(form)}catch(error){toast(error.message||'Không thể lưu dữ liệu.',true)}});
document.addEventListener('click',e=>{
 const menu=e.target.closest('[data-nav]');if(menu){ui.page=menu.dataset.nav;ui.search='';ui.status='all';render();return}
 const tab=e.target.closest('[data-tab]');if(tab){const [page,value]=tab.dataset.tab.split(':');if(page==='inbound')ui.inboundTab=value;if(page==='outbound')ui.outboundTab=value;ui.search='';render();return}
 const el=e.target.closest('[data-action]');if(!el)return;
 if(el.dataset.action==='closeOverlay'){if(e.target===el)closeModal();return}
 try{eventAction(el.dataset.action,el.dataset.key)}catch(error){toast(error.message||'Không thể hoàn tất thao tác.',true)}
});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.name==='chartSku'){ui.chosenSku=el.value;render();return}
 if(el.dataset.filter){ui[el.dataset.filter]=el.value;render()}
});
document.addEventListener('input',e=>{
 const el=e.target;if(el.dataset.filter!=='search')return;ui.search=el.value;
 const start=el.selectionStart,end=el.selectionEnd;render();
 const next=document.querySelector('input[data-filter="search"]');if(next){next.focus();try{next.setSelectionRange(start,end)}catch{}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
